import numpy as np
from scipy import stats
from sklearn.linear_model import LogisticRegression
from sklearn.feature_selection import mutual_info_classif
from collections import defaultdict

MAX_DRIVERS = 5

def design(feats):
    # Find features with strong association to outcome
    effects = []
    for i, fid in enumerate(feats.ids):
        if feats.types[i] == 'derived':
            continue
        # Use Welch's t-test as proxy for effect size
        t_stat = feats.x[:, i].std() * (feats.x[feats.y==1, i].mean() - feats.x[feats.y==0, i].mean()) / (
            feats.x[:, i].std()**2 / (feats.y.sum() - 1) + 
            feats.x[:, i].std()**2 / (len(feats.y) - feats.y.sum() - 1)
        )
        p_val = 2 * (1 - stats.t.cdf(abs(t_stat), len(feats.y) - 2))
        if p_val < 0.05:
            effects.append((fid, abs(t_stat)))

    # Sort by effect size
    effects.sort(key=lambda x: x[1], reverse=True)

    # Identify potential drivers among top features
    drivers = []
    seen = set()

    # Build correlation matrix
    corr_matrix = np.corrcoef(feats.x.T)

    # Group correlated features
    clusters = []
    used = set()

    for i, fid1 in enumerate(feats.ids):
        if fid1 in used:
            continue
        cluster = [fid1]
        used.add(fid1)

        for j, fid2 in enumerate(feats.ids):
            if i != j and fid2 not in used and abs(corr_matrix[i,j]) >= 0.6:
                cluster.append(fid2)
                used.add(fid2)

        if len(cluster) > 1:
            clusters.append(cluster)

    # For each cluster, select the one with highest effect size
    for cluster in clusters:
        best_fid = max(cluster, key=lambda fid: max([eff[1] for eff in effects if eff[0] == fid], default=0))
        drivers.append(best_fid)

    # Add any remaining top features that aren't part of clusters
    remaining_effects = [(fid, effect) for fid, effect in effects if fid not in [f for c in clusters for f in c]]
    for fid, _ in remaining_effects[:MAX_DRIVERS - len(drivers)]:
        if len(drivers) < MAX_DRIVERS:
            drivers.append(fid)

    # Select columns for regression (include drivers and their correlates)
    columns = set()
    for fid in drivers:
        columns.add(fid)
        # Add correlated features to avoid multicollinearity issues
        fid_idx = feats.column(fid)
        for j, other_fid in enumerate(feats.ids):
            if other_fid != fid and abs(corr_matrix[fid_idx, j]) >= 0.6:
                columns.add(other_fid)

    # Create products for top correlations
    products = set()
    if len(drivers) >= 2:
        # Look for pairs of drivers with high correlation
        for i, d1 in enumerate(drivers):
            for j, d2 in enumerate(drivers[i+1:], i+1):
                idx1 = feats.column(d1)
                idx2 = feats.column(d2)
                if abs(corr_matrix[idx1, idx2]) >= 0.6:
                    products.add((d1, d2))

    # Simple weighted score using top features
    loadings = {}
    for i, fid in enumerate(feats.ids):
        if fid in columns:
            # Weight based on effect size
            effect_size = max([eff[1] for eff in effects if eff[0] == fid], default=0)
            loadings[fid] = effect_size

    return Design(
        drivers=tuple(drivers),
        columns=tuple(columns),
        products=tuple(products),
        loadings=loadings
    )
